ns.Data.Rotations = {
  arcane = "Arcane Fire (raid): open Pyroblast, build 4 Arcane Blast stacks and refresh within 18 s. Priority: Pyroblast at 3 Heating Up > Fire Blast on cooldown (until 3 Heating Up) > Arcane Wrath on cooldown > Arcane Missiles with Missile Barrage > Arcane Blast to keep 4 stacks. AoE: pre-pull Flamestrike, Blink in, Arcane Explosion on cooldown, Presence of Mind + Flamestrike when the first one ends (8 s).",
  arcane_leveling = "Max range: Frostbolt (slow) > Arcane Wrath > Arcane Blast 1-3x until Missile Barrage > Arcane Missiles > Frost Nova > Arcane Wrath > Fire Blast > wand to finish. Let Arcane Blast drop (cost +100% per stack). Use Clearcasting on multi-stack Arcane Blast or Arcane Wrath. AoE: gather, Frost Nova, Cone of Cold, Arcane Explosion spam (not on 3 or fewer mobs).",
  fire = "Deep Fire (Combustion): open Pyroblast, Scorch to 5 Improved Scorch stacks (refresh within 30 s). Priority: Pyroblast at 3 Heating Up > Fire Blast on cooldown (1 stack guaranteed, 2 on crit; each stack -1.5 s Pyroblast cast) > Arcane Blast (keep 1-2 stacks) > Arcane Missiles on Missile Barrage > Fireball filler > Scorch to maintain the debuff. AoE: Flamestrike, Blink in, Blast Wave on cooldown > Cone of Cold > Flamestrike (8 s) > Arcane Explosion.",
  fire_leveling = "Max range: Frostfire Bolt / Pyroblast (Fireball before you have them) > Arcane Blast 1-2x until Missile Barrage > Arcane Missiles > Pyroblast at 3 Heating Up > Fire Blast on cooldown > Scorch filler > wand under ~15% or when out of mana. AoE: Frost Nova, Flamestrike, Blast Wave (or Cone of Cold), Arcane Explosion; don't overlap slows; Mana Shield only near death.",
  frostfire = "Frostfire Bolt build: open Pyroblast, Scorch to 5 stacks. Pyroblast at 3 Heating Up > Fire Blast on cooldown > Frostfire Bolt until 3 Heating Up > Scorch to maintain. On Fingers of Frost, batch an instant (preferably Fire Blast) with the 2nd stack. AoE: Flamestrike, Blink in, Blast Wave > Cone of Cold (can proc Fingers of Frost) > Flamestrike > Arcane Explosion.",
  frost = "Pre-pull: Arcane Intellect, Ice Armor or Mage Armor, Ice Barrier at pull, precast Frostbolt. Priority: at 5 Winter's Chill stacks batch Cone of Cold with the next Frostbolt > at 1 Fingers of Frost stack batch Ice Lance with Frostbolt > (Frostbite builds) frozen target: batch Ice Lance > recast Ice Barrier when Frigid Power has <=3 s > Frostbolt. AoE 3+: Cone of Cold on cooldown, Cold Snap to reset it, Blizzard filler.",
  frost_leveling = "Max-range Frostbolt; keep Arcane Blast at 1 stack (buff); react to procs: Frostbite freeze on hit -> Frostbolt + batched Ice Lance (Cone of Cold if Ice Lance is on cooldown); Fingers of Frost on cast -> Frostbolt, then Frostbolt + batched Ice Lance on the 2nd stack. Arcane Missiles on Missile Barrage. Frost Nova and back up when enemies close in; Fire Blast or wand to finish.",
  mana = "Five-second rule: spending mana stops Spirit regen for 5 s (wand finishing lets it resume sooner; wanding doesn't interrupt it). Mage Armor keeps 50% of Spirit regen while casting and Arcane Meditation 3/3 another 50% (100% in combat from ~level 34, Icy Veins). Regen formula 13 + Spirit/4 every 2 s (Wowhead). MP5 always applies. Evocation restores most mana over 8 s (use near ~5% mana; Spirit improves it). Conjure food, water and a mana gem at login; Major Mana Potion has a 2 min cooldown.",
